    'onboarding.01.body': 'Vi ste predsjednik zemlje u ratu, ne osvajač koji juri kartu. Ovdje nema ekrana pobjede. Ovaj rat je negativne sume: može se samo preživjeti, okončati ili pogoršati. Vaš zadatak je da oblikujete kako se tragedija odvija - i koliko tešku cijenu ostavlja za sobom.',
    'onboarding.02.title': 'Karta nije rezultat',
    'onboarding.02.body': 'Boje frakcija pokazuju političku kontrolu; rubovi fronta označavaju gdje vaše snage dodiruju neprijatelja. Ali ne igrajte za kartu. Tokom godina borbi front se jedva pomjeri dok se zemlja prazni - stotine hiljada raseljenih da bi se linija pomjerila za nekoliko naselja. Zemlja nije rezultat.',
    'onboarding.03.title': 'Brifing',
    'onboarding.03.body': 'Terenska alatna traka drži pregled karte blizu: ratna karta daje stanje na terenu, zapisi otvaraju arhivu Štaba armije, a Kodeks drži historijski kontekst. Prvo pročitajte sto; predsjednički sto pretvara pregled u radnju.',
    'onboarding.04.title': 'Pregled prije odluke',
    'onboarding.04.body': 'Statusna traka ratne sobe prikazuje trenutnu fazu, prioritete i preglede na čekanju. Prioritetni dosje navodi šta štab označava kao hitno. Otvorite Štab armije za uvid u spremnost korpusa, zalihe i komandno trenje prije obaveze.',
    'onboarding.05.title': 'Predsjednički sto',
    'onboarding.05.body': 'Prije nastavka poteza, predsjednički sto prikazuje svaki izbor na čekanju. Svaki red otvara svoj resolver ili štabski panel iz kojeg dolazi - otvorite ga, odlučite, vratite se. Riješite što možete; odgodite što morate.',
    'onboarding.06.title': 'Komandujete kroz generale',
    'onboarding.06.body': 'Komandujete kroz svoje generale, ne nad pojedinačnim jedinicama. Vi sami nikad ne gurate brigade - svaki napad ide kroz operaciju korpusa. Vaši komandanti predlažu operacije; vi odobravate, odbijate ili prisilno pokrećete protiv njihovog suda uz cijenu komandnog autoriteta. Vi zadajete smjer i nosite posljedice; oni vode bitku.',
    'onboarding.07.title': 'Nastavite i pročitajte posljedice',
    'onboarding.07.body': 'Kada nastavite potez, rat ide naprijed za jednu sedmicu. Panel posljedica izvještava šta se promijenilo: bitke, dobijen ili izgubljen teren, gubici, raseljeni, komandni ishodi. Pročitajte ga - ljudska cijena je dio zapisa, ne fusnota. Sljedeći potez počinje posljedicama ovog.',
    'onboarding.08.title': 'Knjiga cijene je rezultat',
    'onboarding.08.body': 'Knjiga ratne cijene je vaš pravi rezultat, ne karta. Zauzimanje teritorije može sniziti vašu konačnu ocjenu; raseljeni i iscrpljeni teže protiv vas, a zločin trajno truje presudu - nikad se ne nagrađuje. Kada diplomatija konačno nametne nagodbu, teško stečena poluga i ljudska cijena odlučuju kako historija sudi vašem predsjedništvu.',
    'aar.title': 'Izvještaj poslije dejstva',
    'aar.close': 'Zatvori izvještaj poslije dejstva',
