    'chiefOfStaff.alert.cohesion.aggressive.suffix': ' je u nevolji. Moramo ih ojačati ili povući. ',
    'chiefOfStaff.alert.operation.precise.prefix': 'Operacija ',
    'chiefOfStaff.alert.operation.precise.suffix': ' je završila pripremu. Čeka odluku KRENI/STANI. ',
    'chiefOfStaff.alert.operation.aggressive.suffix': ' je spremna za pokretanje. Sto duže čekamo, neprijatelj se više priprema. ',
    'chiefOfStaff.alert.defense.precise.prefix': 'Sektor ',
    'chiefOfStaff.alert.defense.precise.suffix': ' ima premalo ljudstva u odnosu na sirinu fronta. Ranjivost: visoka. ',
    'chiefOfStaff.alert.defense.aggressive.suffix': ' je izložen - jedan pritisak i linija puca. Trebaju nam brigade tamo odmah. ',
    'chiefOfStaff.corpsCommandFallback': 'komanda jednog korpusa',
    'chiefOfStaff.strain.cautious.strained': 'Moram napomenuti da su komandni odnosi sa {corpsName} i dalje pod pritiskom nakon nedavnih predsjedničkih intervencija. Štab izvršava naredbe, ali odnos zahtijeva pažljivo upravljanje.',
    'chiefOfStaff.strain.cautious.compromised': 'Duboko sam zabrinut zbog komandnog odnosa sa {corpsName}. Ponovljene direktne intervencije stvorile su ozbiljno institucionalno trenje. Štab izvršava naredbe, ali je njihovo povjerenje u lanac komandovanja narušeno.',
    'chiefOfStaff.strain.precise.strained': 'Status komandnog autoriteta: komandni odnos sa {corpsName} je pod pritiskom. Nedavne direktne intervencije unijele su trenje u ciklus planiranja. Kohezija štaba ostaje funkcionalna.',
    'chiefOfStaff.strain.precise.compromised': 'Status komandnog autoriteta: komandni odnos sa {corpsName} je narušen. Ponovljene direktne intervencije stvorile su institucionalno trenje. Preporučujem obnovu delegiranog komandovanja prije daljih operacija.',
    'chiefOfStaff.strain.aggressive.strained': 'Štab {corpsName} je još uz nas, ali su intervencije ostavile trag. Izvršit će naredbe, ali potrošili smo dio dobre volje. Vrijedi imati na umu prije sljedeće intervencije.',
    'chiefOfStaff.strain.aggressive.compromised': 'Situacija sa {corpsName} je ozbiljna. Previše intervencija narušilo je komandni odnos. Štab izvršava naredbe, ali radi pod pritiskom. Moramo ih neko vrijeme pustiti da vode svoje operacije.',
    'chiefOfStaff.strain.commanderFriction.strained': 'Neriješen komandni incident opterećuje odnose sa {corpsName}. Štab ostaje funkcionalan, ali incident zahtijeva pregled.',
    'chiefOfStaff.strain.commanderFriction.compromised': 'Neriješeni incidenti s komandantom ozbiljno su ugrozili odnose sa {corpsName}. Izvor je unutar komandnog odnosa i zahtijeva pregled.',
    'chiefOfStaff.strain.exhaustion.strained': 'Operativna iscrpljenost opterećuje komandni ciklus u {corpsName}. Za oporavak je potreban niži tempo.',
    'chiefOfStaff.strain.exhaustion.compromised': 'Operativna iscrpljenost ugrozila je komandni ciklus u {corpsName}. Operativni tempo treba smanjiti dok se korpus oporavlja.',
    'chiefOfStaff.strain.mixed.strained': 'Više zabilježenih pritisaka opterećuje komandne odnose sa {corpsName}. Zajedno pregledati komandne incidente, intervencije i iscrpljenost.',
    'chiefOfStaff.strain.mixed.compromised': 'Više zabilježenih pritisaka ugrozilo je komandne odnose sa {corpsName}. Uzroci zahtijevaju usklađenu pažnju.',
