    'intro.identity.situationLabel': 'Situacija',
    'intro.identity.escapeLabel': 'Ono čemu ne možete umaći',
    'intro.forceBriefing.RBiH.name': 'ARBiH',
    'intro.forceBriefing.RBiH.body': 'Vojska Republike Bosne i Hercegovine okuplja se iz teritorijalne odbrane, policije i dobrovoljaca. Slabo naoružana, ali braneći domovinu, njen rani opstanak zavisi od držanja urbanih centara i kupovine vremena za organizaciju.',
    'intro.forceBriefing.RS.name': 'VRS',
    'intro.forceBriefing.RS.body': 'Vojska Republike Srpske nasljeđuje opremu, oficire i doktrinu JNA. Profesionalna i teško naoružana, VRS ima odlučujuću početnu prednost, ali dugoročno trpi iscrpljivanje dok se rezerve tanje.',
    'intro.forceBriefing.HRHB.name': 'HVO',
    'intro.forceBriefing.HRHB.body': 'Hrvatsko vijeće obrane organizuje se oko zapadne Hercegovine i enklava u srednjoj Bosni. Sposoban, ali geografski rascjepkan, HVO balansira između saveza s ARBiH i vlastitih teritorijalnih ambicija.',
    'intro.identity.RBiH.identity': 'Vi ste predsjednik Predsjedništva Republike Bosne i Hercegovine, priznate od svijeta 6. aprila i opkoljene istog dana. Predsjedavate višenacionalnom državom koju je polovina njenih vlastitih građana digla na oružje da je razori.',
    'intro.identity.RBiH.situation': 'Priznanje je stiglo; oružje nije. Međunarodni embargo na oružje veže vam ruke dok visovi iznad Sarajeva, Tuzle i Drine pripadaju bivšoj saveznoj armiji koja je zadržala svoje tenkove i svoje oficire. Vaši branioci su teritorijalne jedinice, policija i dobrovoljci — Bošnjaci, Srbi, Hrvati — nadjačani u naoružanju za red veličine. Držite gradove i tek malo zemlje između njih. Ubijanje u Zvorniku i Bijeljini je već počelo.',
    'intro.identity.RBiH.escape': 'Morate braniti građansku republiku s vojskom građana koju borbe već pretvaraju u jednonacionalnu silu — a nemate viška oružja za jaz između onoga u šta vjerujete i onoga što možete održati.',
    'intro.identity.RS.identity': 'Vi ste predsjednik Republike Srpske. Narodna skupština zasjeda, a pred vama leži šest strateških ciljeva srpskog naroda u Bosni. Usvojiti ih znači pokrenuti vojsku. Potpis je vaš.',
    'intro.identity.RS.situation': 'Vi započinjete rat na koji svi ostali tek pokušavaju odgovoriti. JNA vam ostavlja svoju artiljeriju, svoje korpuse, svoju logistiku i nadmoćne položaje nad svakim muslimanskim i hrvatskim gradom koji je bitan. Koridor kroz Posavinu, granica na Drini, podijeljeno Sarajevo — svaki cilj je karta, a svaka karta presijeca naselja u kojima živi vaš neprijatelj. Prednost je danas vaša, i potpuna je.',
    'intro.identity.RS.escape': 'Vaš vlastiti komandant vojske ustao je u ovoj Skupštini i otvoreno upozorio da se koridor na Drini i podjela Sarajeva ne mogu postići bez djela koja predstavljaju genocid. Odluka je sada na stolu, i samo je vaša: pokrenuti vojsku znači preuzeti odgovornost za ono što ona učini.',
    'intro.identity.HRHB.identity': 'Vi ste predsjednik Herceg-Bosne, hrvatske paradržave proglašene u Grudama — vođa koji, istini za volju, odgovara dvjema prijestolnicama: onoj u Sarajevu s kojom ste u savezu, i onoj u Zagrebu koja vas je stvorila.',
    'intro.identity.HRHB.situation': 'Vaša snaga leži u zapadnoj Hercegovini; vaš najizloženiji narod razasut je po srednjoj Bosni, u dolinama gdje su Bošnjaci većina, a VRS je bliža prijetnja. HVO je sposoban ali rascijepljen po zemlji koju ne može povezati. Danas su vaši topovi okrenuti istom neprijatelju kao i sarajevski — u Mostaru, u Posavini. Iza vas, zagrebačko pokroviteljstvo nosi svoju cijenu, i vlastitu kartu.',
    'intro.identity.HRHB.escape': 'Savez koji održava vaše razasute enklave u životu služi prijestolnici čiji se naum za Bosnu razlikuje od sarajevskog — i svaka brigada, svaki grad, svaka naredba vuče vas između to dvoje. Ne možete u potpunosti zadovoljiti nijednu stranu.',
    'statusStrip.openWarRecord': 'Otvori ratnu hroniku',
