    'decisionRoom.card.addressNation.explanation': 'Obratite se narodu putem etera. Može podići moral — ali ima dvije oštrice: prkos učvršćuje linije, apel svijetu razdražuje pokrovitelja, a podignuta očekivanja se kasnije mogu izjaloviti.',
